import sys
lines = sys.stdin.read().splitlines()
if lines:
    n = int(lines[0])
    intervals = []
    for line in lines[1:1+n]:
        se = [int(x) for x in line.split()]
        if len(se) == 2: intervals.append(se)
    intervals.sort(key=lambda x: x[1])
    count = 0
    end = float('-inf')
    for s, e in intervals:
        if s >= end: end = e
        else: count += 1
    print(count)
